  try {
    const r = await api('GET', '/health');
    const served = r.headers.get('X-Beacon-Replica') || r.json?.replica || '?';
    leader = r.json?.leader ?? '?';
    $('replica').textContent = `served by ${served} · leader ${leader}`;

