static void routes(Javalin app, Store store) {
    app.post("/api/schedules/{shareId}", ctx -> publish(ctx, store));
    app.get("/api/schedules/{shareId}/current", ctx -> current(ctx, store));
    app.before("/api/reports", ctx -> { if (ctx.method() == io.javalin.http.HandlerType.POST) RateLimit.check(ctx); });
    app.post("/api/reports", ctx -> report(ctx, store));
    app.get("/api/reports", ctx -> fetch(ctx, store));
    app.get("/api/whereami", Api::whereami);

/** ephemeral public key (65) + GCM nonce (12) + GCM tag (16): the smallest possible envelope. */
static final int MIN_CIPHERTEXT = 93;
static final int MAX_CIPHERTEXT = 2048;

/** Owner publishes the public key for each of the next epochs. Idempotent; called every 15 minutes while the tab is open. */
private static void publish(Context ctx, Store store) {
    String shareId = shareId(ctx);
    JsonNode body = ctx.bodyAsClass(JsonNode.class);
    JsonNode keys = body.path("keys");
    if (!keys.isArray() || keys.isEmpty() || keys.size() > MAX_KEYS_PER_PUBLISH) {
        throw new BadRequestResponse("keys must be 1.." + MAX_KEYS_PER_PUBLISH + " entries");
    }
    long now = Epochs.current();
    List<Store.PublishedKey> parsed = new ArrayList<>();
    for (JsonNode k : keys) {
        long epoch = k.path("epoch").asLong(-1);
        if (epoch < now - 1 || epoch > now + Epochs.PUBLISHED_AHEAD + 1) {
            throw new BadRequestResponse("epoch " + epoch + " is outside the publishable window around " + now);
        }
        byte[] pub = decode(k.path("publicKey").asText(""), "publicKey");
        if (pub.length != 65 || pub[0] != 0x04) throw new BadRequestResponse("publicKey must be a 65-byte uncompressed P-256 point");
        parsed.add(new Store.PublishedKey(epoch, pub));
    }
    store.putSchedule(shareId, parsed);
    Log.out("[Schedule] share=%s keys=%d epochs=%d..%d", shareId, parsed.size(),
            parsed.get(0).epoch(), parsed.get(parsed.size() - 1).epoch());
    ctx.status(201).json(Map.of("shareId", shareId, "stored", parsed.size(), "epoch", now));

/** Finder asks for the key of the current epoch. The answer is a public key: safe to hand to anyone. */
private static void current(Context ctx, Store store) {
    String shareId = shareId(ctx);
    long epoch = Epochs.current();
    var key = store.keyFor(shareId, epoch);
    if (key.isEmpty()) {
        ctx.status(404).json(Map.of("error", "no key published for this share id and epoch", "epoch", epoch));
        return;
    }
    ctx.json(Map.of(
            "shareId", shareId,
            "epoch", epoch,
            "epochSeconds", Epochs.SECONDS,
            "publicKey", encode(key.get().publicKey())

/** Finder posts an opaque envelope under the hash of the key it encrypted to. */
private static void report(Context ctx, Store store) {
    JsonNode body = ctx.bodyAsClass(JsonNode.class);
    String keyHash = body.path("keyHash").asText("");
    if (!KEY_HASH.matcher(keyHash).matches()) throw new BadRequestResponse("keyHash must be a base64url SHA-256");
    byte[] ciphertext = decode(body.path("ciphertext").asText(""), "ciphertext");
    if (ciphertext.length < MIN_CIPHERTEXT || ciphertext.length > MAX_CIPHERTEXT) {
        throw new BadRequestResponse("ciphertext must be " + MIN_CIPHERTEXT + ".." + MAX_CIPHERTEXT + " bytes");
    }
    store.putReport(decode(keyHash, "keyHash"), ciphertext);
    Log.out("[Report] %s · %d B of ciphertext stored under key hash %s… · ip %s",
            RateLimit.finderName(ctx), ciphertext.length, keyHash.substring(0, 8), clientIp(ctx));
    ctx.status(201).json(Map.of("stored", true, "bytes", ciphertext.length));

/** Owner fetches by key hash, one hash per epoch it wants to check. */
private static void fetch(Context ctx, Store store) {
    List<String> hashes = ctx.queryParams("h");
    if (hashes.isEmpty() || hashes.size() > MAX_HASHES_PER_FETCH) {
        throw new BadRequestResponse("pass 1.." + MAX_HASHES_PER_FETCH + " h= parameters");
    }
    for (String h : hashes) if (!KEY_HASH.matcher(h).matches()) throw new BadRequestResponse("bad key hash " + h);
    long started = System.nanoTime();
    Map<String, List<Store.Report>> found = store.reports(hashes);
    Map<String, List<Map<String, String>>> out = new HashMap<>();
    int total = 0;
    for (var e : found.entrySet()) {
        List<Map<String, String>> list = new ArrayList<>();
        for (Store.Report r : e.getValue()) list.add(Map.of("ts", r.ts(), "ciphertext", encode(r.ciphertext())));
        out.put(e.getKey(), list);
        total += list.size();
    }
    Log.out("[Fetch] %d key hashes in %d ms on %s threads · %d reports found", hashes.size(),
            (System.nanoTime() - started) / 1_000_000, Thread.currentThread().isVirtual() ? "virtual" : "platform", total);
    ctx.json(out);

 * Initialization-on-demand holder. The JVM initializes a class exactly once, under its own lock, the first
 * time something touches it. Holder is not touched until session() runs, so the session is lazy, and no
 * caller after the first ever takes a lock. SingletonTest hits this from 64 threads at once.
 */
private static final class Holder {
    static final CqlSession INSTANCE = connect();
}

static CqlSession session() {
    return Holder.INSTANCE;

static CqlSession connect() {
    String host = Main.env("CASSANDRA_HOST", "127.0.0.1");
    int port = Integer.parseInt(Main.env("CASSANDRA_PORT", "9042"));
    CONNECTS.incrementAndGet();
    Log.out("[Cassandra] connecting to %s:%d", host, port);
    DriverConfigLoader config = DriverConfigLoader.programmaticBuilder()
            .withDuration(DefaultDriverOption.REQUEST_TIMEOUT, Duration.ofSeconds(10))
            .withString(DefaultDriverOption.REQUEST_CONSISTENCY, "LOCAL_QUORUM")
            .build();
    CqlSession bootstrap = CqlSession.builder()
            .addContactPoint(new InetSocketAddress(host, port))
            .withLocalDatacenter(Main.env("CASSANDRA_DC", "datacenter1"))
            .withConfigLoader(config)
            .build();
    applySchema(bootstrap);
    Log.out("[Cassandra] connected, schema applied");
    return bootstrap;

CassandraStore() {
    CqlSession s = Cassandra.session();
    insertKey = s.prepare("INSERT INTO beacon.schedules (share_id, epoch, public_key) VALUES (?, ?, ?)");
    selectKey = s.prepare("SELECT public_key FROM beacon.schedules WHERE share_id = ? AND epoch = ?");
    insertReport = s.prepare("INSERT INTO beacon.reports (key_hash, ts, ciphertext) VALUES (?, ?, ?)");
    selectReports = s.prepare("SELECT ts, ciphertext FROM beacon.reports WHERE key_hash = ? LIMIT " + REPORTS_PER_HASH);

public void putSchedule(String shareId, List<PublishedKey> keys) {
    // All rows share one partition (share_id), so an unlogged batch is one write to one node, not 97.
    BatchStatement batch = BatchStatement.newInstance(BatchType.UNLOGGED);
    for (PublishedKey key : keys) {
        batch = batch.add(insertKey.bind(shareId, key.epoch(), ByteBuffer.wrap(key.publicKey())));
    }
    Cassandra.session().execute(batch);

public void putReport(byte[] keyHash, byte[] ciphertext) {
    // The row's TTL comes from the table default (7 days). timeuuid gives newest-first order for free.
    Cassandra.session().execute(insertReport.bind(ByteBuffer.wrap(keyHash), Uuids.timeBased(), ByteBuffer.wrap(ciphertext)));

 * One partition read per hash, all in flight at once. Virtual threads make blocking driver calls cheap
 * to park: 97 tasks, 97 virtual threads, a handful of carrier threads. invokeAll keeps the answer order
 * and rethrows the first failure. The executor is per call and closed by try-with-resources, so nothing
 * leaks across requests.
 */
@Override
public Map<String, List<Report>> reports(List<String> keyHashes) {
    List<Callable<List<Report>>> tasks = new ArrayList<>();
    for (String h : keyHashes) tasks.add(() -> reportsFor(h));
    Map<String, List<Report>> out = new LinkedHashMap<>();
    try (ExecutorService fanOut = Executors.newVirtualThreadPerTaskExecutor()) {
        List<Future<List<Report>>> results = fanOut.invokeAll(tasks);
        for (int i = 0; i < keyHashes.size(); i++) {
            List<Report> list = results.get(i).get();
            if (!list.isEmpty()) out.put(keyHashes.get(i), list);
        }
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
        throw new IllegalStateException("fetch interrupted", e);
    } catch (java.util.concurrent.ExecutionException e) {
        throw new IllegalStateException("fetch failed: " + e.getCause(), e.getCause());
    }
    return out;

List<Report> reportsFor(String keyHash) {
    ByteBuffer hash = ByteBuffer.wrap(Base64.getUrlDecoder().decode(keyHash));
    List<Report> list = new ArrayList<>();
    for (Row row : Cassandra.session().execute(selectReports.bind(hash))) {
        Instant at = Instant.ofEpochMilli(Uuids.unixTimestamp(row.getUuid("ts")));
        list.add(new Report(at.toString(), bytes(row.getByteBuffer("ciphertext"))));

 * The interview question, run against production code: release 64 threads at the same instant and count how
 * many distinct instances come back. One is the only acceptable answer.
 */
class SingletonTest {

    static final int THREADS = 64;

    /** Park every worker at a gate, open it, collect what each one got. Set membership is identity. */
    static <T> Set<T> hammer(Supplier<T> getInstance) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(THREADS);
        CountDownLatch ready = new CountDownLatch(THREADS);
        CountDownLatch go = new CountDownLatch(1);
        try {
            List<Future<T>> results = new ArrayList<>();
            for (int i = 0; i < THREADS; i++) {
                results.add(pool.submit(() -> {
                    ready.countDown();
                    go.await();
                    return getInstance.get();
                }));
            }
            ready.await();
            go.countDown();
            Set<T> distinct = ConcurrentHashMap.newKeySet();
            for (Future<T> f : results) distinct.add(f.get());
            return distinct;
        } finally {
            pool.shutdownNow();
